  {t="C", seg=4, q={92745}, obj={1}, names={"The State of the Mines"}, text="North-west to the Jangolode Mine: kill 4 Kobold Diggers (12-13) inside", zone="Westfall", map=1436, x=45.3, y=20.0, path={{55.4,47.2},{55.4,43.6},{53.4,40.6},{49.6,37.9},{49.0,33.1},{50.0,31.6},{50.0,28.0},{48.0,23.5},{48.0,19.0},{45.6,18.1}}},
  {t="C", seg=4, q={92745}, obj={2}, names={"The State of the Mines"}, text="South-west to the Gold Coast Quarry on the west coast: kill 6 Riverpaw Miners (14-15) in the quarry. The gnolls here drop Gnoll Paws", zone="Westfall", map=1436, x=29.8, y=48.1, path={{45.0,18.4},{42.8,18.7},{38.2,23.2},{37.4,25.6},{37.8,31.6},{35.0,36.1},{35.6,45.1},{30.8,46.6}}},
  {t="C", seg=4, q={13}, names={"The People's Militia"}, text="Kill 15 Defias Pillagers and 15 Defias Looters (13-15) around the Gold Coast Quarry and the Alexston Farmstead just east of it. Pillagers cast Fireball: Earth Shock it. Finish the bandanas and gnoll paws here too", zone="Westfall", map=1436, x=31.3, y=49.3},
  {t="C", seg=4, q={399}, names={"Humble Beginnings"}, text="Alexston Farmstead: A Simple Compass is in Alexston's Chest at the farmstead (follow the arrow)", zone="Westfall", map=1436, x=36.2, y=54.5},
  {t="C", seg=4, q={102,153}, names={"Patrolling Westfall","Red Leather Bandanas"}, text="Still short of 8 Gnoll Paws (Riverpaw gnolls at the quarry) or 15 Red Leather Bandanas (any Defias)? Finish them before heading back east", zone="Westfall", map=1436, x=34.0, y=50.0},
  {t="T", seg=4, q={102}, names={"Patrolling Westfall"}, text="Captain Danuvin, in the tower", zone="Westfall", map=1436, x=56.4, y=47.6},
  {t="T", seg=4, q={13}, names={"The People's Militia"}, text="Gryan Stoutmantle", zone="Westfall", map=1436, x=56.3, y=47.5},
  {t="A", seg=4, q={14,65}, names={"The People's Militia","The Defias Brotherhood"}, text="Gryan gives both. Keep The Defias Brotherhood: Wiley is in Lakeshire, next segment. Do not take the Deadmines quests", zone="Westfall", map=1436, x=56.3, y=47.5},
  {t="T", seg=4, q={153}, names={"Red Leather Bandanas"}, text="Scout Galiaan", zone="Westfall", map=1436, x=54.0, y=53.0},
