  {t="T", seg=4, q={14}, names={"The People's Militia"}, text="Gryan Stoutmantle", zone="Westfall", map=1436, x=56.3, y=47.5},
  {t="N", seg=4, arg="Optional dungeon: The Deadmines, levels 17-26", text="The entrance is in Moonbrook, in the south-west of Westfall: through the barn-like building and down the mine tunnels to the portal. Inside: Edwin VanCleef drops An Unsent Letter that starts a quest for Baros Alexston in Stormwind. Quests you picked up for it: Collecting Memories, Oh Brother. . ., Underground Assault. Needs an earlier quest chain this route does not do: Red Silk Bandanas, The Defias Brotherhood.", zone="Westfall", map=1436, x=42.5, y=71.7, dg=2, run=true},
