  {t="T", seg=4, q={92748}, names={"Explosive Consultation"}, text="Sprite Jumpsprocket, an engineer in the Dwarven District. Stop here: her next quest needs 10 Rough Dynamite and the chain ends in the Deadmines", zone="Stormwind City", map=1453, x=62.0, y=30.8},
