  {t="A", seg=5, q={244}, names={"Encroaching Gnolls"}, text="From the Dwarven District leave Stormwind by the main gate and follow the road east: Goldshire, Eastvale Logging Camp, then the Three Corners crossroads just inside Redridge. Guard Parker walks the road there.", zone="Redridge Mountains", map=1433, x=10.2, y=71.5},
  {t="F", seg=5, arg="Lakeshire", text="Follow the road north-east to Lakeshire. Ariena Stormfeather, the gryphon master, stands on the south side of the bridge. Redridge Mongrels (15-16) and Great Goretusks sit next to the road: leave them for now.", zone="Redridge Mountains", map=1433, x=25.5, y=59.4},
  {t="T", seg=5, q={244}, names={"Encroaching Gnolls"}, text="Deputy Feldon, a few steps from the gryphon master", zone="Redridge Mountains", map=1433, x=25.6, y=60.0},
