  {t="A", seg=10, q={69}, names={"The Legend of Stalvan"}, text="Clerk Daltry. For Goldshire, later in this segment", zone="Duskwood", map=1431, x=72.5, y=46.9},
  {t="T", seg=10, q={57}, names={"The Night Watch"}, text="Commander Althea Ebonlocke, in front of the town hall", zone="Duskwood", map=1431, x=73.5, y=46.8},
  {t="A", seg=10, q={58}, names={"The Night Watch"}, text="Commander Althea Ebonlocke. The Plague Spreaders are back at Raven Hill: last loop of this segment", zone="Duskwood", map=1431, x=73.5, y=46.8},
  {t="T", seg=10, q={225}, names={"The Weathered Grave"}, text="Sirra Von'Indi, in the town hall", zone="Duskwood", map=1431, x=72.6, y=47.6},
  {t="T", seg=10, q={377}, names={"Crime and Punishment"}, zone="Duskwood", map=1431, x=71.9, y=47.8, dg=3},
