  {t="T", seg=10, q={69}, names={"The Legend of Stalvan"}, text="Leave Stormwind by the main gate and run to Goldshire (2 minutes). Innkeeper Farley in the Lion's Pride Inn", zone="Elwynn Forest", map=1429, x=43.8, y=65.8},
  {t="A", seg=10, q={70}, names={"The Legend of Stalvan"}, text="Innkeeper Farley. Then open the chest upstairs in the inn for Stalvan's Undelivered Letter", zone="Elwynn Forest", map=1429, x=43.8, y=65.8},
