  {t="T", seg=10, q={74}, names={"The Legend of Stalvan"}, text="Leave by the main gate, through Goldshire and east along the road to the Eastvale Logging Camp. Marshal Haggard is at Elwynn 84.6,69.4", zone="Elwynn Forest", map=1429, x=84.6, y=69.4},
