  {t="A", seg=10, q={128}, names={"Blackrock Bounty"}, text="Follow the road east over Three Corners to Lakeshire. Guard Howe stands at the south end of the bridge (26.4,57.9)", zone="Redridge Mountains", map=1433, x=26.4, y=57.9},
