  {t="C", seg=10, q={126}, names={"Howling in the Hills"}, text="Go north out of Lakeshire into the canyons. Yowler (25) stands in the gnoll camp at 22.6,21.4. Everything here is grey or green to you", zone="Redridge Mountains", map=1433, x=22.6, y=21.4},
  {t="C", seg=10, q={128}, names={"Blackrock Bounty"}, text="Further north, the Blackrock camp (21-31,6-17): kill 15 Blackrock Champions (24-25)", zone="Redridge Mountains", map=1433, x=24.5, y=12.0, path={{24.9,19.3}}},
  {t="A", seg=10, q={219}, names={"Missing In Action"}, text="Corporal Keeshan, held in the same camp (23.3,12.6). Clear the orcs around him first, then accept: it is an escort", zone="Redridge Mountains", map=1433, x=23.3, y=12.6},
  {t="C", seg=10, q={219}, names={"Missing In Action"}, text="Walk with Keeshan back to Lakeshire. He fights everything on the way; keep Healing Wave for him and do not run ahead", zone="Redridge Mountains", map=1433, x=26.0, y=30.0, path={{24.9,13.0},{25.2,19.6},{28.2,24.1},{28.2,27.4}}},
