  {t="T", seg=10, q={128}, names={"Blackrock Bounty"}, text="Guard Howe, at the bridge", zone="Redridge Mountains", map=1433, x=26.4, y=57.9},
  {t="C", seg=10, q={180}, names={"Wanted: Lieutenant Fangore"}, text="Lieutenant Fangore (26) is far east in Galardell Valley, in the Shadowhide camp at 75.1,37.1. Take the road east past Stonewatch (Ghost Wolf). Gnolls stand with him: Stoneclaw Totem and kill him first", zone="Redridge Mountains", map=1433, x=75.1, y=37.1},
