  {t="A", seg=11, q={98463}, names={"Talk of the Town"}, text="Barkeep Kelly, in the same inn (needs level 28): Talk of the Town. Only a message for the barkeep in Booty Bay; you carry it until the route gets there", zone="Hillsbrad Foothills", map=1424, x=51.6, y=58.6},
  {t="T", seg=11, q={647}, names={"MacKreel's Moonshine"}, text="Brewmeister Bilger, in the inn", zone="Hillsbrad Foothills", map=1424, x=52.1, y=58.7},
  {t="A", seg=11, q={98071}, names={"Brewer's Trade"}, text="Brewmeister Bilger (new in Forever)", zone="Hillsbrad Foothills", map=1424, x=52.1, y=58.7},
  {t="T", seg=11, q={98219}, names={"The Shamed Lieutenant"}, text="Lieutenant Farren Orinelle, in the inn", zone="Hillsbrad Foothills", map=1424, x=51.5, y=58.4},
