  {t="A", seg=11, q={525}, names={"Further Mysteries"}, text="Prospector Stormpike. It goes back to Southshore: keep it until segment 15", zone="Ironforge", map=1455, x=74.6, y=11.7},
  {t="A", seg=11, q={1453}, names={"Reclaimers' Business in Desolace"}, text="Roetten Stonehammer, Reclaimers Inc., in the Hall of Explorers. For Desolace (segment 12)", zone="Ironforge", map=1455, x=70.0, y=21.3},
  {t="T", seg=11, q={637}, names={"Sully Balloo's Letter"}, text="Sara Balloo (Questie: 63.5,67.3; the ForeverChanges pins for old Ironforge quests use another map scale and are not used here)", zone="Ironforge", map=1455, x=63.5, y=67.3},
  {t="A", seg=11, q={683}, names={"Sara Balloo's Plea"}, text="Sara Balloo", zone="Ironforge", map=1455, x=63.5, y=67.3},
  {t="T", seg=11, q={683}, names={"Sara Balloo's Plea"}, text="King Magni Bronzebeard, in the High Seat", zone="Ironforge", map=1455, x=39.1, y=56.2},
  {t="A", seg=11, q={686}, names={"A King's Tribute"}, text="King Magni Bronzebeard", zone="Ironforge", map=1455, x=39.1, y=56.2},
  {t="T", seg=11, q={686}, names={"A King's Tribute"}, text="Grand Mason Marblesten (39.0,88.0). Do not take the next step: it needs Alterac Granite", zone="Ironforge", map=1455, x=39.0, y=88.0},
  {t="A", seg=11, q={1179}, names={"The Brassbolts Brothers"}, text="Pilot Longbeard (Questie puts him at 72.7,94.0; the ForeverChanges page says the Hall of Arms). The crate goes to the Shimmering Flats in segment 13", zone="Ironforge", map=1455, x=72.7, y=94.0},
  {t="TRAIN", seg=11, text="Ironforge: Eldrun Stormbreaker (47.6, 13.5). Level 32 spells if you are 32. This is your last trainer until 36: the next two segments are in Kalimdor"},
  {t="N", seg=11, arg="Before you leave: repair, buy food and water, bank what you do not need", text="Start saving gold now: the ram and riding training at 40 are expensive"},
  {t="FLY", seg=11, arg="Menethil Harbor", text="Gryth Thurden", zone="Ironforge", map=1455, x=55.5, y=47.7},
  {t="A", seg=11, q={2924}, names={"Essential Artificials"}, text="Klockmort Spannerspan in Tinker Town. 12 Essential Artificials from the Artificial Extrapolators inside.", zone="Ironforge", map=1455, x=67.9, y=46.1, dg=7},
  {t="A", seg=11, q={2930}, names={"Data Rescue"}, text="Master Mechanic Castpipe in Tinker Town. A Prismatic Punch Card: it takes a chain of punch-card machines through the dungeon. Needs level 25.", zone="Ironforge", map=1455, x=69.8, y=48.1, dg=7},
  {t="A", seg=11, q={2929}, names={"The Grand Betrayal"}, text="High Tinker Mekkatorque in Tinker Town. Kill Mekgineer Thermaplugg, the last boss. Needs level 25.", zone="Ironforge", map=1455, x=68.8, y=49.0, dg=7},
  {t="N", seg=11, arg="Optional dungeon: Gnomeregan, levels 29-38", text="The entrance is in the west of Dun Morogh, past Brewnall Village: take the lift down and go through the workshop tunnels to the portal. More quests need a small lead-in first: Tinkmaster Overspark in Tinker Town (Save Techbot's Brain!, after a pointer from Brother Sarno in Stormwind) and Ozzie Togglevolt in Kharanos (Gnogaine, after a pointer from Gnoarn in Tinker Town). Inside: Kernobee gives an escort quest that ends with Scooty in Booty Bay. Quests you picked up for it: Gyrodrillmatic Excavationators, Essential Artificials, Data Rescue, The Grand Betrayal.", zone="Dun Morogh", map=1426, x=24.3, y=39.8, dg=7, run=true},
  {t="T", seg=11, q={2924}, names={"Essential Artificials"}, zone="Ironforge", map=1455, x=67.9, y=46.1, dg=7},
  {t="T", seg=11, q={2930}, names={"Data Rescue"}, zone="Ironforge", map=1455, x=69.8, y=48.1, dg=7},
  {t="T", seg=11, q={2929}, names={"The Grand Betrayal"}, zone="Ironforge", map=1455, x=68.8, y=49.0, dg=7},
  {t="T", seg=11, q={98223}, names={"Old Habits"}, text="Captain Stoutfist, Menethil Keep", zone="Wetlands", map=1437, x=9.9, y=57.4},
  {t="A", seg=11, q={1302}, names={"James Hyal"}, text="Vincent Hyal, in the Deepwater Tavern (needs level 30): James Hyal. A message for the clerk in Theramore; you carry it until the route gets there", zone="Wetlands", map=1437, x=10.8, y=60.4},
  {t="T", seg=11, q={270}, names={"The Doomed Fleet"}, text="Glorin Steelbrow, in the Deepwater Tavern", zone="Wetlands", map=1437, x=10.6, y=60.6},
  {t="A", seg=11, q={321}, names={"Lightforge Iron"}, text="Glorin Steelbrow", zone="Wetlands", map=1437, x=10.6, y=60.6},
  {t="T", seg=11, q={321}, names={"Lightforge Iron"}, text="The Waterlogged Chest in the wreck of the Flying Osprey, south of the docks (12.1,64.2)", zone="Wetlands", map=1437, x=12.1, y=64.2},
  {t="A", seg=11, q={324}, names={"The Lost Ingots"}, text="The same chest", zone="Wetlands", map=1437, x=12.1, y=64.2},
  {t="C", seg=11, q={324}, names={"The Lost Ingots"}, text="Bluegill Raiders (28-29) around the wreck and on the shore south of it drop the 5 Lightforge Ingots. They are green to you now", zone="Wetlands", map=1437, x=13.0, y=65.5},
  {t="T", seg=11, q={324}, names={"The Lost Ingots"}, text="Glorin Steelbrow. Do not take Blessed Arm (322)", zone="Wetlands", map=1437, x=10.6, y=60.6},
  {t="T", seg=11, q={1248}, names={"The Missing Diplomat"}, text="Mikhail, at the bar in the Deepwater Tavern", zone="Wetlands", map=1437, x=10.6, y=60.8},
  {t="A", seg=11, q={1249}, names={"The Missing Diplomat"}, text="Mikhail. Read the next step before you accept", zone="Wetlands", map=1437, x=10.6, y=60.8},
  {t="C", seg=11, q={1249}, names={"The Missing Diplomat"}, text="Tapoke \"Slim\" Jahn (34) sits near Mikhail (10.5,60.3). When you accept he tries to leave and fights. Put Earthbind and Stoneclaw Totem at the door before you accept, Frost Shock him, and beat him until he gives up. If he gets away, abandon and take the quest again", zone="Wetlands", map=1437, x=10.5, y=60.3},
  {t="T", seg=11, q={1249}, names={"The Missing Diplomat"}, text="Mikhail", zone="Wetlands", map=1437, x=10.6, y=60.8},
  {t="A", seg=11, q={1250}, names={"The Missing Diplomat"}, text="Tapoke \"Slim\" Jahn, once he has given up", zone="Wetlands", map=1437, x=10.5, y=60.3},
  {t="T", seg=11, q={1250}, names={"The Missing Diplomat"}, text="Mikhail", zone="Wetlands", map=1437, x=10.6, y=60.8},
  {t="A", seg=11, q={1264}, names={"The Missing Diplomat"}, text="Mikhail. For Commander Samaul in Theramore (segment 13)", zone="Wetlands", map=1437, x=10.6, y=60.8},
  {t="N", seg=11, arg="Take the boat from Menethil Harbor to Auberdine", text="Segment done. In the log: 525, 563, 1026, 1179, 1264, 1453. Your hearthstone stays in Southshore until Astranaar"},
  {t="T", seg=12, q={98209}, names={"Bloom of the Heavens"}, text="Thundris Windweaver, the elder in the building at the north end of Auberdine: hand him Nord'el", zone="Darkshore", map=1439, x=37.4, y=40.1},
  {t="T", seg=12, q={1275}, names={"Researching the Corruption"}, zone="Darkshore", map=1439, x=38.3, y=43.0, dg=4},
  {t="FLY", seg=12, arg="Astranaar", text="Caylais Moonfeather, on the Auberdine dock where the boat lands", zone="Darkshore", map=1439, x=36.3, y=45.6},
  {t="S", seg=12, arg="Astranaar", text="Innkeeper Kimlya. You hearth back here twice in this segment", zone="Ashenvale", map=1440, x=37.0, y=49.2},
  {t="A", seg=12, q={1035}, names={"Fallen Sky Lake"}, text="Pelturas Whitemoon, Astranaar (37.4,51.8)", zone="Ashenvale", map=1440, x=37.4, y=51.8},
  {t="A", seg=12, q={4581}, names={"Kayneth Stillwind"}, text="Shindrell Swiftfire, Astranaar (34.7,48.8)", zone="Ashenvale", map=1440, x=34.7, y=48.8},
  {t="A", seg=12, q={1022}, names={"The Howling Vale"}, text="Take the road west to the Shrine of Aessina (22,53). Sentinel Melyria Frostshadow. The quest text says Forest Song, but Questie and ForeverChanges both place her here", zone="Ashenvale", map=1440, x=22.2, y=53.0},
  {t="A", seg=12, q={1021}, names={"Vile Satyr! Dryads in Danger!"}, text="Illiyana, the dryad next to her", zone="Ashenvale", map=1440, x=21.7, y=53.3},
  {t="A", seg=12, q={86757}, names={"Slowing the Orc Advance"}, text="Back east through Astranaar, then south-east to Silverwind Refuge on Mystral Lake. Shandrina (new in Forever). The orcs for it are in the far south-east: you kill them on the loop below", zone="Ashenvale", map=1440, x=49.4, y=67.0},
  {t="C", seg=12, q={1022}, names={"The Howling Vale"}, text="Go north across the road into the Howling Vale. The Tome of Mel'Thandris stands in the ruined shrine at 50.5,39.1; the way in is through the short cave at 53.0,37.6. Worgen (27-30) stand close together: pull singles, and leave the rare if one is up. Click the tome", zone="Ashenvale", map=1440, x=50.5, y=39.1, path={{51.7,38.3}}, cave=true},
  {t="C", seg=12, q={1026}, names={"Raene's Cleansing"}, text="East of the vale, along the road to Felwood: Withered Ancients (26-27, at 54-59,33-42) and Crazed Ancients (27-28, at 57-62,31-45) drop the Wooden Key. Then open the Worn Chest in the small glade west of the road at 54.4,35.4 for the Iron Shaft", zone="Ashenvale", map=1440, x=56.5, y=36.5},
  {t="T", seg=12, q={1026}, names={"Raene's Cleansing"}, text="Shael'dryn, the dryad at the moonwell beside the main road (53.5,46.2)", zone="Ashenvale", map=1440, x=53.5, y=46.2},
  {t="A", seg=12, q={1027}, names={"Raene's Cleansing"}, text="Shael'dryn. The last rod piece is at Dor'danil in the south-east: you pick it up later on this loop", zone="Ashenvale", map=1440, x=53.5, y=46.2},
  {t="T", seg=12, q={1021}, names={"Vile Satyr! Dryads in Danger!"}, text="Follow the main road east. Anilia lies at the edge of the Xavian satyr camp, north of the road (78.3,44.8). Kill the one or two satyrs next to her; the rest of the camp comes later", zone="Ashenvale", map=1440, x=78.3, y=44.8},
  {t="A", seg=12, q={1031}, names={"The Branch of Cenarius"}, text="Anilia", zone="Ashenvale", map=1440, x=78.3, y=44.8},
  {t="T", seg=12, q={4581}, names={"Kayneth Stillwind"}, text="Kayneth Stillwind at Forest Song, at the east end of the road (85.2,44.7)", zone="Ashenvale", map=1440, x=85.2, y=44.7, path={{82.3,46.3},{84.7,46.3}}},
  {t="A", seg=12, q={1011}, names={"Forsaken Diseases"}, text="Kayneth Stillwind", zone="Ashenvale", map=1440, x=85.2, y=44.7},
  {t="A", seg=12, q={98417}, names={"Vengeful Trail"}, text="Maseara Autumnmoon, Forest Song (new in Forever)", zone="Ashenvale", map=1440, x=86.2, y=45.8},
  {t="C", seg=12, q={98417}, names={"Vengeful Trail"}, text="Satyrnaar, the satyr camp south-west of Forest Song (about 80-82,48-52). Find the Vine-Wrapped Scroll: the data does not say whether it drops from the satyrs (28-30) or lies in the camp, so kill and look around. Earth Shock the Hellcallers", zone="Ashenvale", map=1440, x=81.0, y=50.0},
  {t="T", seg=12, q={98417}, names={"Vengeful Trail"}, text="Maseara Autumnmoon", zone="Ashenvale", map=1440, x=86.3, y=45.8},
  {t="A", seg=12, q={98418}, names={"Shared Fury"}, text="Maseara Autumnmoon", zone="Ashenvale", map=1440, x=86.3, y=45.8},
  {t="C", seg=12, q={98418,1031}, names={"Shared Fury","The Branch of Cenarius"}, text="Xavian (77-80,42-48): 5 Xavian Rogues, 5 Felsworn, 5 Betrayers and 5 Hellcallers (28-30). There are only 2 Betrayer spawns: wait for them to come back. Geltharis (32) stands at the north end at 78.0,42.4: clear around him, then Stoneclaw Totem and Earth Shock his casts. He drops the Branch of Cenarius", zone="Ashenvale", map=1440, x=78.4, y=45.4},
  {t="T", seg=12, q={98418}, names={"Shared Fury"}, text="Maseara Autumnmoon at Forest Song. The ForeverChanges page also shows a hand-in at Satyrnaar (81.0,50.2): if she is not at Forest Song, look there", zone="Ashenvale", map=1440, x=86.3, y=45.8},
  {t="C", seg=12, q={1011}, names={"Forsaken Diseases"}, text="South from Forest Song, past the Warsong lumber camp (stay west of it). The Forsaken camp is outside the Dor'danil Barrow Den; the Bottles of Disease stand on the ground at 75.3,72.0. Forsaken here are 28-30 and stealthed in part: Lightning Shield up", zone="Ashenvale", map=1440, x=75.3, y=72.0, path={{78.9,46.3},{76.3,52.8},{71.4,58.8},{71.6,69.0}}},
  {t="C", seg=12, q={1027}, names={"Raene's Cleansing"}, text="The Rusty Chest with the Iron Pommel is at Dor'danil too. Its spot is not in the data: check in front of and just inside the barrow den entrance and along the hill behind the Forsaken camp", zone="Ashenvale", map=1440, x=76.0, y=73.5},
  {t="C", seg=12, q={86757}, names={"Slowing the Orc Advance"}, text="Warsong orcs (scouts and grunts, about 28-30) drop Jagged Orcish Swords (6) and Curved Orcish Daggers (4). ForeverChanges saw the drops south-west of Dor'danil toward Fallen Sky Lake (65-75,75-85) and around the lumber camp south of Forest Song (85-90,50-65). Camps are Horde-flagged: pull stragglers at the edges", zone="Ashenvale", map=1440, x=70.0, y=79.0},
  {t="C", seg=12, q={1035}, names={"Fallen Sky Lake"}, text="Fallen Sky Lake: the Shadethicket Oracle (30) stands on the island in the middle (66.7,82.2). Bark Rippers and Stone Movers around it are 25-27. He drops the Fallen Moonstone", zone="Ashenvale", map=1440, x=66.7, y=82.2},
  {t="T", seg=12, q={1011}, names={"Forsaken Diseases"}, text="Back north to Kayneth Stillwind at Forest Song (finish the orc weapons at the lumber camp on the way if you are short)", zone="Ashenvale", map=1440, x=85.2, y=44.7, path={{68.8,82.2},{71.8,75.6},{71.4,58.8},{76.3,52.8},{76.5,50.4},{78.9,46.3},{84.7,46.3}}},
  {t="A", seg=12, q={1012}, names={"Insane Druids"}, text="Kayneth Stillwind", zone="Ashenvale", map=1440, x=85.2, y=44.7},
  {t="C", seg=12, q={1012}, names={"Insane Druids"}, text="Back to the Dor'danil Barrow Den, this time inside: Taneel Darkwood (77.2,74.0), Uthil Mooncall (78.0,72.7) and Mavoris Cloudsbreak (75.1,74.2), all level 32, with Severed druids (28-30) between them. Clear each room first. They cast: keep Earth Shock for their heals and roots", zone="Ashenvale", map=1440, x=76.8, y=73.6, path={{84.7,46.3},{78.9,46.3},{76.3,52.8},{71.2,59.4},{71.6,69.0}}},
  {t="T", seg=12, q={1012}, names={"Insane Druids"}, text="Kayneth Stillwind", zone="Ashenvale", map=1440, x=85.2, y=44.7, path={{71.6,69.0},{71.2,59.4},{76.3,52.8},{76.5,50.4},{78.9,46.3},{84.7,46.3}}},
  {t="F", seg=12, arg="Talrendis Point", text="Follow the road east from Forest Song over the bridge into Azshara. Talrendis Point is right behind the border; Jarrodenus is the hippogryph master", zone="Azshara", map=1447, x=11.9, y=77.6},
  {t="FLY", seg=12, arg="Astranaar", text="Jarrodenus"},
  {t="T", seg=12, q={1035}, names={"Fallen Sky Lake"}, text="Pelturas Whitemoon", zone="Ashenvale", map=1440, x=37.4, y=51.8},
  {t="T", seg=12, q={1027}, names={"Raene's Cleansing"}, text="Run east along the road to Shael'dryn at the moonwell (53.5,46.2)", zone="Ashenvale", map=1440, x=53.5, y=46.2},
  {t="A", seg=12, q={1028}, names={"Raene's Cleansing"}, text="Shael'dryn", zone="Ashenvale", map=1440, x=53.5, y=46.2},
  {t="T", seg=12, q={1028}, names={"Raene's Cleansing"}, text="The Hidden Shrine, in the woods just south-east of the moonwell (56.4,49.2)", zone="Ashenvale", map=1440, x=56.4, y=49.2},
  {t="A", seg=12, q={1055}, names={"Raene's Cleansing"}, text="The Hidden Shrine", zone="Ashenvale", map=1440, x=56.4, y=49.2},
  {t="T", seg=12, q={1055}, names={"Raene's Cleansing"}, text="Shael'dryn", zone="Ashenvale", map=1440, x=53.5, y=46.2},
