  {t="C", seg=14, q={194}, names={"Raptor Mastery"}, text="10 Stranglethorn Raptors (33-34): on the hills west of the camp, above the coast", zone="Stranglethorn Vale", map=1434, x=25.8, y=16.1, path={{35.6,12.1},{33.8,12.1},{32.8,10.6},{29.0,10.3},{28.0,14.8}}},
