  {t="N", seg=14, arg="Walk the road south to Booty Bay", text="A long walk in Ghost Wolf: stay on the road all the way to the south tip and through the shark-jaw tunnel. Grom'gol, on the west coast half way down, is a Horde base: do not leave the road there.", zone="Stranglethorn Vale", map=1434, x=27.5, y=77.8},
  {t="F", seg=14, arg="Booty Bay", text="Gyll, the gryphon master on the upper level at the east end of town", zone="Stranglethorn Vale", map=1434, x=27.5, y=77.8},
  {t="S", seg=14, arg="Booty Bay", text="Innkeeper Skindle, in the Salty Sailor Tavern", zone="Stranglethorn Vale", map=1434, x=27.0, y=77.3},
  {t="T", seg=14, q={98463}, names={"Talk of the Town"}, text="Nixxrax Fillamug, the barkeep in the same tavern: Talk of the Town", zone="Stranglethorn Vale", map=1434, x=27.0, y=77.2},
  {t="T", seg=14, q={210}, names={"Krazek's Cookery"}, text="Krazek, upstairs in the building next to the inn. Do NOT take Favor for Krazek: its Lesser Bloodstone Ore only comes from Drywhisker Gorge in the Arathi Highlands.", zone="Stranglethorn Vale", map=1434, x=26.9, y=77.2},
